from pathlib import Path; import subprocess; p=Path('AGENTS.md'); t=p.read_text(encoding='utf-8'); h='## Browser bridge visible-chat transport'; n=chr(10); s=n+n+h+n+n+'Harde operationele regel: bridge-taken moeten als gewone zichtbare assistant-chattekst worden geplaatst; commentary of tool-output alleen telt niet als verzending.'+n+'Als de gebruiker de taak niet ziet, geldt de taak als NIET VERZONDEN en moet hij opnieuw zichtbaar worden gestuurd.'+n+'Vermijd bridge-sentinelvoorbeelden in gewone uitleg of payloadvelden, omdat de browserparser die als echte taakgrenzen kan interpreteren.'+n; changed=h not in t; p.write_text(t.rstrip()+s+n,encoding='utf-8') if changed else None; subprocess.run(['git','add','AGENTS.md'],check=True) if changed else None; subprocess.run(['git','commit','-m','docs: persist bridge visible-chat rule','--','AGENTS.md'],check=True) if changed else None; print('RULE_PRESENT',h in p.read_text(encoding='utf-8')); print('CHANGED',changed); print('HEAD',subprocess.run(['git','rev-parse','HEAD'],text=True,capture_output=True,check=True).stdout.strip())